def own_text(tag):
    parts = [s for s in tag.find_all(string=True, recursive=False) if isinstance(s, str)]
    return ' '.join([p.strip() for p in parts]).strip()

header = None
for tag in soup.find_all(True):
    if tag.name in ('a', 'script', 'style'):
        continue
    if '類別' in own_text(tag):
        header = tag
        break
result = []
if header is not None:
    block = None
    node = header
    tried = 0
    while node is not None and tried < 5:
        node = node.find_next_sibling()
        tried += 1
        if node is None:
            break
        if node.find('a', href=True) is not None:
            block = node
            break
    if block is not None:
        for a in block.find_all('a', href=True):
            name = a.get_text(strip=True)
            if name and name not in result:
                result.append(name)
